def transform(grid):
    """Overlay the two equal panels, marking positions occupied in both with 2."""
    h = len(grid)
    w = len(grid[0])
    # Find a solid one-column divider that bisects the grid into equal panels.
    divider = None
    for c in range(w):
        color = grid[0][c]
        if all(row[c] == color for row in grid) and c == w - 1 - c:
            divider = c
            break
    if divider is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and c == w // 2:
                divider = c
                break
    if divider is None:
        raise ValueError("no centered solid divider")
    width = divider
    left = [row[:width] for row in grid]
    right = [row[divider + 1:] for row in grid]
    if width != len(right[0]):
        raise ValueError("panels are not equal width")
    return [[2 if left[r][c] != 0 and right[r][c] != 0 else 0
             for c in range(width)] for r in range(h)]

